\begin{lemma}
\label{expander-subdiv-order}
Fix $d\in\mathbb{R}_{>1}$. Let $k_n = \left\lceil\left(\frac{n}{\log^d n}\right)^{1/(d-1)}\right\rceil$, and let $n_s = n+\frac{3n}{2}(k_n-1)$. There exist positive constants $C_1 = C_1(d),C_2 = C_2(d)$ and $N_3=N_3(d)$ such
that
\[
C_1n_s^{1-1/d}\log n_s \leq n \leq C_2n_s^{1-1/d}\log n_s,
\]
for every $n\geq N_3$.
\end{lemma}

\begin{proposition}\label{prop4.3}
	Let $\bm{v}$ be a nonnegative bivariate matrix-valued functions. Suppose that $\bm{V} =\Vityone{\bm{v}} \in\Ge{\alpha}{K}$ with $\alpha<1$ and that
	\[\Res_{\bm{v}}^{\infty}(t) \preceq \frac{A}{(1+t)^{\gamma}} \bm{V}, \quad \forall t\geq 0.\]
	Then the function $\bm{\psi} = \sum_{n\geq 1} \bm{v}^{\star n}$ is well defined and satisfies, for all $t> 0$ and all $0<\delta <1$,
	\begin{equation*}
	\Res_{\bm{\psi}}^{\infty}(t) \preceq \frac{A \big(1+\frac{\gamma}{\delta \log(1/\alpha)}\big)^{\gamma}}{(1+t)^{\gamma(1-\delta)}}\bm{V} (\Id-\bm{V})^{-2} + \bm{V}^{\lfloor\frac{\gamma(1-\delta) \log(1+t)}{\log(1/\alpha)}\rfloor+2} (\Id-\bm{V})^{-2}.
	\end{equation*}
	In particular,
	\begin{equation*}
		\Vvert \Res_{\bm{\psi}}^{\infty}(t) \Vvert_{\infty} \leq \frac{\alpha K(K+1) \Big[ A\big(1+\frac{\gamma}{\delta \log(1/\alpha)}\big)^{\gamma} + 1\Big]}{(1-\alpha)^2(1+t)^{\gamma(1-\delta)}}, \quad \forall t>0.
	\end{equation*}
\end{proposition}

\begin{lemma}\label{lemma:collection_of_paths}
    Let $h, r \geq 1$, $a \geq 16h$ and let $G$ be an $r$-expander for $r \geq 10^{23}h^2\Delta(G)\log^3\Delta(G)$.
    Let moreover $U \subseteq V(G)$ and  $S_1, \dots, S_{2h} \subseteq U$ be disjoint sets such that for each $i \in [2h]$
    \begin{enumerate}
        \item $|U| \leq r/(10^{16})$ and $|S_i| \geq a$, 
        \item any subset $S \subseteq S_i$ with $|S| \geq |S_i| /2$ has $|N(S)| \geq r$, \emph{and}
        \item for each $v \in \left(V(G) \setminus U\right) \cup S_1 \cup \dots \cup S_{2h}$ we have $|N(v) \cap (S_1\cup \dots \cup S_{2h})| \leq ha/(10^{8}h^2\log^3\Delta(G))$.
    \end{enumerate}
    Then, there exists a subset $I \subseteq [2h]$ of size $h$ and a collection of disjoint paths $\{P_{i, j} : \{i, j\} \in \binom{I}{2}\}$ such that $P_{i, j}$ is a path from $S_i$ to $S_j$, $|P_{i, j} \cap U| =2$ and the only edges spanned by $\bigcup_{i, j} V(P_{i, j})$ are $\bigcup_{i, j} E(P_{i, j})$.
\end{lemma}

\begin{thm}\label{m0}
Let $(X,d)$ and $(Y,\rho)$ be $\bf MCD$-spaces.
Then the following statements are equivalent.
\begin{enumerate}
\item $(X,d)$ and $(Y,\rho)$ are isometric.

\item The representing trees
\(
T_X=T_X(r_X,l_X)
\) and
\(T_Y=T_Y(r_Y,l_Y)
\)
are isomorphic as labeled rooted trees.

\item The trees $T_X(l_X)$ and $T_Y(l_Y)$ are isomorphic as labeled trees.

\item The equality
\begin{equation}
    \label{m2}
C(X)=C(Y)
\end{equation}
holds.

\item The equality
\begin{equation*}
D(X)=D(Y)
\end{equation*}
holds.
\end{enumerate}
\end{thm}
